pub fn encode(n: u64) -> String {
    if n == 0 {
        return "zero".to_string();
    }

    const ONES: [&str; 20] = [
        "zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine",
        "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen",
        "seventeen", "eighteen", "nineteen",
    ];

    const TENS: [&str; 8] = [
        "", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety",
    ];

    const SCALES: [&str; 7] = [
        "", "thousand", "million", "billion", "trillion", "quadrillion", "quintillion",
    ];

    let mut chunks = Vec::new();
    let mut v = n;
    while v > 0 {
        chunks.push(v % 1000);
        v /= 1000;
    }

    let mut parts: Vec<String> = Vec::new();
    for (i, chunk) in chunks.iter().enumerate() {
        if *chunk == 0 {
            continue;
        }
        let words = chunk_to_words(*chunk, &ONES, &TENS);
        let scale = SCALES[i];
        if scale.is_empty() {
            parts.push(words);
        } else {
            parts.push(format!("{words} {scale}"));
        }
    }

    // parts is in reverse order (least significant first)
    parts.reverse();
    parts.join(" ")
}

fn chunk_to_words(chunk: u64, ones: &[&str; 20], tens: &[&str; 8]) -> String {
    let mut parts: Vec<String> = Vec::new();
    let hundreds = chunk / 100;
    let remainder = chunk % 100;
    if hundreds > 0 {
        parts.push(format!("{} hundred", ones[hundreds as usize]));
    }
    if remainder > 0 {
        parts.push(two_digits(remainder, ones, tens));
    }
    parts.join(" ")
}

fn two_digits(v: u64, ones: &[&str; 20], tens: &[&str; 8]) -> String {
    if v < 20 {
        return ones[v as usize].to_string();
    }
    let t = v / 10;
    let o = v % 10;
    if o == 0 {
        tens[t as usize].to_string()
    } else {
        format!("{}-{}", tens[t as usize], ones[o as usize])
    }
}
