/// Spell out a number (0 through `u64::MAX`) in English.
///
/// Numbers are broken into chunks of three digits, each chunk is spelled out,
/// and the appropriate scale word (thousand, million, ...) is appended.
pub fn encode(n: u64) -> String {
    if n == 0 {
        return "zero".to_string();
    }

    let mut chunks = Vec::new();
    let mut v = n;
    while v > 0 {
        chunks.push(v % 1000);
        v /= 1000;
    }

    let mut parts: Vec<String> = Vec::new();
    for (i, &chunk) in chunks.iter().enumerate() {
        if chunk == 0 {
            continue;
        }
        let words = chunk_to_words(chunk);
        match SCALES.get(i) {
            Some(scale) if !scale.is_empty() => parts.push(format!("{words} {scale}")),
            _ => parts.push(words),
        }
    }

    // `chunks` was built least-significant-first; emit most-significant-first.
    parts.reverse();
    parts.join(" ")
}

/// Spell out a value in the range 0..=999.
fn chunk_to_words(chunk: u64) -> String {
    let mut parts: Vec<String> = Vec::new();

    let hundreds = chunk / 100;
    let remainder = chunk % 100;

    if hundreds > 0 {
        parts.push(format!("{} hundred", ONES[hundreds as usize]));
    }
    if remainder > 0 {
        parts.push(two_digits(remainder));
    }

    parts.join(" ")
}

/// Spell out a value in the range 0..=99.
fn two_digits(v: u64) -> String {
    if v < 20 {
        return ONES[v as usize].to_string();
    }
    let tens = v / 10;
    let ones = v % 10;
    if ones == 0 {
        TENS[tens as usize].to_string()
    } else {
        format!("{}-{}", TENS[tens as usize], ONES[ones as usize])
    }
}

const ONES: [&str; 20] = [
    "zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten",
    "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen",
    "nineteen",
];

const TENS: [&str; 10] = [
    "", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety",
];

const SCALES: [&str; 7] = [
    "", "thousand", "million", "billion", "trillion", "quadrillion", "quintillion",
];
